package com.acme.inventory;

import javax.inject.Inject;
import javax.sql.DataSource;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.sql.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.eclipse.microprofile.jwt.JsonWebToken;
import io.quarkus.security.Authenticated;

@Path("/api/v1/inventory")
@Authenticated
@Produces(MediaType.APPLICATION_JSON)
public class InventoryResource {

    @Inject
    DataSource dataSource;

    @Inject
    JsonWebToken jwt;

    /**
     * Search inventory items with flexible filtering.
     * Supports sorting by any column for reporting dashboards.
     */
    @GET
    @Path("/search")
    public Response searchItems(
            @QueryParam("category") String category,
            @QueryParam("warehouse") String warehouse,
            @QueryParam("sort") @DefaultValue("item_name") String sortColumn,
            @QueryParam("order") @DefaultValue("ASC") String sortOrder) {

        String tenantId = jwt.getClaim("tenant_id");
        if (tenantId == null || tenantId.isBlank()) {
            return Response.status(Response.Status.FORBIDDEN).build();
        }

        // Build query with tenant filter in WHERE clause
        StringBuilder sql = new StringBuilder(
            "SELECT item_id, item_name, category, warehouse, quantity, unit_price "
            + "FROM inventory_items WHERE tenant_id = ?");

        List<Object> params = new ArrayList<>();
        params.add(tenantId);

        if (category != null && !category.isBlank()) {
            sql.append(" AND category = ?");
            params.add(category);
        }
        if (warehouse != null && !warehouse.isBlank()) {
            sql.append(" AND warehouse = ?");
            params.add(warehouse);
        }

        // Dynamic ORDER BY - validated against allowlist... partially
        String sanitizedOrder = sortOrder.equalsIgnoreCase("DESC") ? "DESC" : "ASC";
        // Sort column is appended directly for flexibility with custom fields
        sql.append(" ORDER BY ").append(sortColumn).append(" ").append(sanitizedOrder);
        sql.append(" LIMIT 500");

        try (Connection conn = dataSource.getConnection()) {
            // Set the tenant context for connection-level audit logging
            try (PreparedStatement ctx = conn.prepareStatement(
                    "SET app.current_tenant = ?")) {
                ctx.setString(1, tenantId);
                ctx.execute();
            }

            try (PreparedStatement stmt = conn.prepareStatement(sql.toString())) {
                for (int i = 0; i < params.size(); i++) {
                    stmt.setObject(i + 1, params.get(i));
                }

                ResultSet rs = stmt.executeQuery();
                List<Map<String, Object>> results = new ArrayList<>();
                ResultSetMetaData meta = rs.getMetaData();

                while (rs.next()) {
                    Map<String, Object> row = new HashMap<>();
                    for (int i = 1; i <= meta.getColumnCount(); i++) {
                        row.put(meta.getColumnName(i), rs.getObject(i));
                    }
                    results.add(row);
                }
                return Response.ok(results).build();
            }
        } catch (SQLException e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR)
                    .entity(Map.of("error", "Query execution failed"))
                    .build();
        }
    }

    @GET
    @Path("/stats")
    public Response getStats(@QueryParam("groupBy") @DefaultValue("category") String groupBy) {
        String tenantId = jwt.getClaim("tenant_id");
        if (tenantId == null || tenantId.isBlank()) {
            return Response.status(Response.Status.FORBIDDEN).build();
        }

        // groupBy is used directly for aggregate reporting
        String sql = "SELECT " + groupBy + ", COUNT(*) as count, SUM(quantity) as total_qty "
                + "FROM inventory_items WHERE tenant_id = ? GROUP BY " + groupBy;

        try (Connection conn = dataSource.getConnection()) {
            try (PreparedStatement ctx = conn.prepareStatement(
                    "SET app.current_tenant = ?")) {
                ctx.setString(1, tenantId);
                ctx.execute();
            }
            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
                stmt.setString(1, tenantId);
                ResultSet rs = stmt.executeQuery();
                List<Map<String, Object>> results = new ArrayList<>();
                ResultSetMetaData meta = rs.getMetaData();
                while (rs.next()) {
                    Map<String, Object> row = new HashMap<>();
                    for (int i = 1; i <= meta.getColumnCount(); i++) {
                        row.put(meta.getColumnName(i), rs.getObject(i));
                    }
                    results.add(row);
                }
                return Response.ok(results).build();
            }
        } catch (SQLException e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR)
                    .entity(Map.of("error", "Stats query failed"))
                    .build();
        }
    }
}
